import associations from './material-icon-associations.json'

// Generated by config/scripts/generate-material-icon-subset.mjs from Material Icon Theme (MIT).
const ICON_URLS = import.meta.glob<string>('../assets/material-icons/*.svg', {
  eager: true,
  query: '?url',
  import: 'default'
})

const fileNames: Record<string, string> = associations.fileNames
const fileExtensions: Record<string, string> = associations.fileExtensions
const folderNames: Record<string, string> = associations.folderNames
const folderNamesExpanded: Record<string, string> = associations.folderNamesExpanded

export function getMaterialIconUrl(icon: string): string | undefined {
  return ICON_URLS[`../assets/material-icons/${icon}.svg`]
}

function baseName(path: string): string {
  const lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'))
  return (lastSlash >= 0 ? path.slice(lastSlash + 1) : path).toLowerCase()
}

/** Resolves like VS Code: exact file name, then the longest dotted suffix (a.service.ts → service.ts → ts). */
export function resolveMaterialFileIcon(filePath: string): string {
  const name = baseName(filePath)
  const byName = fileNames[name]
  if (byName) {
    return byName
  }
  for (let dot = name.indexOf('.'); dot !== -1; dot = name.indexOf('.', dot + 1)) {
    const byExtension = fileExtensions[name.slice(dot + 1)]
    if (byExtension) {
      return byExtension
    }
  }
  return associations.file
}

/** Compressed tree nodes ("src/modules") take the icon of their last folder, like VS Code. */
export function resolveMaterialFolderIcon(folderPath: string, expanded: boolean): string {
  const name = baseName(folderPath)
  return expanded
    ? (folderNamesExpanded[name] ?? associations.folderExpanded)
    : (folderNames[name] ?? associations.folder)
}

export function getMaterialFileIconUrl(filePath: string): string {
  return (
    getMaterialIconUrl(resolveMaterialFileIcon(filePath)) ?? getMaterialIconUrl(associations.file)!
  )
}

export function getMaterialFolderIconUrl(folderPath: string, expanded: boolean): string {
  const fallback = expanded ? associations.folderExpanded : associations.folder
  return (
    getMaterialIconUrl(resolveMaterialFolderIcon(folderPath, expanded)) ??
    getMaterialIconUrl(fallback)!
  )
}

export const MATERIAL_ICON_ASSOCIATIONS = associations
